import { Component, input } from '@angular/core';
import { StatusSummary } from '../summary/summary';

// The sheet's counters, always on show: its people (retired included), its claims per status and
// its due-total and overdue-total. Each repeats a figure shown elsewhere and is fed from the same source.
@Component({
  selector: 'app-header',
  template: `
    <header aria-label="Sheet counters">
      <ul>
        <li>People: <strong data-testid="header-people-count">{{ peopleCount() }}</strong></li>
        @for (s of statuses(); track s.status) {
          <li>{{ s.status }}: <strong [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</strong></li>
        }
        <li>Due: <strong data-testid="header-due-total">{{ dueTotal() }}</strong></li>
        <li>Overdue: <strong data-testid="header-overdue-total">{{ overdueTotal() }}</strong></li>
      </ul>
    </header>
  `,
})
export class SheetHeader {
  readonly peopleCount = input.required<number>();
  readonly statuses = input.required<readonly StatusSummary[]>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();
}
  protected voidReasonChanged(c: ClaimView, reason: string): void {
    this.chosenVoidReasons.update((chosen) => ({ ...chosen, [c.id]: reason }));
    if (this.claimError()?.id === c.id) this.claimError.set(null);
  }

  protected changeStatus(c: ClaimView, status: ClaimStatus): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const reason = status === 'VOID' ? (this.chosenVoidReasons()[c.id] ?? '') : '';
    if (status === 'VOID' && reason === '' && this.voidReasons.all().length > 0) {
      this.claimError.set({ id: c.id, message: 'Choose a reason from the list to void this claim.' });
      return;
    }
    this.api.changeStatus(sheet.id, c.id, status, reason === '' ? undefined : reason).subscribe({
      next: (saved) => this.saved.emit(saved),
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: status === 'VOID' && err instanceof HttpErrorResponse && err.status === 422
          ? 'Choose a reason from the sheet\'s list to void this claim.'
          : err instanceof HttpErrorResponse && err.status === 403
          ? status === 'SETTLED' && c.openedBy === this.session.user()
            ? 'You opened this claim, so someone else must settle it.'
            : status === 'SETTLED' && c.editedBy === this.session.user()
            ? 'You last edited this claim, so someone else must settle it.'
            : status === 'VOID' && c.status === 'SETTLED'
              ? 'Only a steward may void a settled claim.'
            : `Your role may not ${STATUS_ACTION[status] ?? 'move'} a claim.`
          : err instanceof HttpErrorResponse && err.status === 423
            ? 'This claim is due by inside a closed period.'
            : err instanceof HttpErrorResponse && err.status === 428
              ? status === 'OPEN' ? UNNOTED : UNPROVEN
            : status === 'VOID' && c.status === 'SETTLED'
              ? 'A settled claim can be voided only within 7 days of its settlement.'
            : status === 'SETTLED' && this.deferredOf(c)
              ? `This claim is deferred until ${c.deferredUntil}, so it cannot be settled before then.`
              : `A ${c.status} claim cannot become ${status}.`,
      }),
    });
  }

  protected addProof(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.api.addProof(sheet.id, c.id).subscribe({

    /** Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim and one due by inside a closed
     *  period. */
    @Transactional
    public Claim addProof(String sheetId, String user, long id) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
        refuseIfClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be given a proof");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
        claim.addProof();
        audit.recordChangeOnCommit(sheetId, user, "HOLIDAY_ADDED sheet=" + sheetId + " by=" + user
                + " date=" + saved.getDate());
        refixDueBys(sheetId, saved.getDate());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    private void refixDueBys(String sheetId, LocalDate holiday) {
        Set<LocalDate> dates = holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
                .collect(Collectors.toSet());
        for (Claim claim : claims.findBySheetIdOrderByListedDescIdDesc(sheetId)) {
            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                    || claim.getDueBy().isBefore(holiday)) {
                continue;
            }
            claim.refixDueBy(businessDaysAfter(claim.getDate(), claim.getTerms(), dates));
        }
        claims.flush();
    }

